
local acl=[==[]==]
local xqwix=
(function(...)
local njt={60,152,169,9,188,165,172,172,137,236,62,16,242,48,182,148,41,92,133,79,55}
local wzi=bit32 or bit
local ul=wzi.bxor
for jbj=1,#njt do njt[jbj]=ul(njt[jbj],(41*jbj+106)%256) end
local nfj="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local dwgqh={}
for ljc=1,#nfj do dwgqh[nfj:byte(ljc)]=ljc-1 end
local function mk(str)
  local R={} local acc,nb=0,0
  for kciub=1,#str do
    local v=dwgqh[str:byte(kciub)]
    if v then
      acc=acc*64+v; nb=nb+6
      if nb>=8 then nb=nb-8; R[#R+1]=math.floor(acc/2^nb)%256; acc=acc%2^nb end
    end
  end
  return R
end
local function miuif(key,data)
  local S={} for ngzpd=0,255 do S[ngzpd]=ngzpd end
  local j=0
  for utt=0,255 do
    j=(j+S[utt]+key[(utt%#key)+1])%256
    S[utt],S[j]=S[j],S[utt]
  end
  local O={} local ii=0; j=0
  for n=1,#data do
    ii=(ii+1)%256; j=(j+S[ii])%256; S[ii],S[j]=S[j],S[ii]
    O[n]=string.char(ul(data[n],S[(S[ii]+S[j])%256]))
  end
  return table.concat(O)
end
local code=miuif(njt,mk(""))
local nf,ne=(loadstring or load)("return "..code)
if not nf then error(ne or "rage quit chain error") end
local hhd=nf()
return function(big) return hhd(big) end
end)(...)

return xqwix(acl)
